SELECT MIN(OpenDate) AS OpenDate
FROM schools
WHERE School IN (
    SELECT School
    FROM frpm
    WHERE `Enrollment (K-12)` = (
        SELECT MAX(`Enrollment (K-12)`)
        FROM frpm
    )
);

SELECT MIN(OpenDate) AS OpenDate
FROM schools
WHERE GSoffered = 'K-12';

